questionvariables.text:
/* questionsimplify is 0 so that the form check can reject an unevaluated power such as 3^2. Every value is forced with ev(...,simp). */
/* Exponential f(x) = b^x with b in {2,3,4,5} and input n1 in {-3,-2,-1,2,3}. (b, n1) = (2, 2) is excluded because 2*2 = 2^2 would void the multiplication diagnostic. */
b: rand([2,3,4,5]);
n1: ev(rand(if b=2 then [-3,-2,-1,3] else [-3,-2,-1,2,3]),simp);
f1: b^x;
negn1: ev(-n1,simp);
/* For a negative input the answer is kept as an unsimplified quotient 1/b^k, which has the same structure as a student's typed fraction, so the form check accepts it. */
correctanswer: if ev(n1<0,simp) then 1/ev(b^(-n1),simp) else ev(b^n1,simp);
/* Diagnostic: for a negative input, a negative index read as a negative number (-b^|n1|, never equal to the positive answer);
   for a positive input, the base multiplied by the index (b*n1, never equal to b^n1 once (2,2) is excluded). */
diag1: if ev(n1<0,simp) then ev(-b^(abs(n1)),simp) else ev(b*n1,simp);
